    "torch::Tensor matmul_shared_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code for matrix multiplication with shared memory
matmul_shared = load_inline(
    name="matmul_shared",
    cpp_sources=matmul_shared_cpp_source,
    cuda_sources=matmul_shared_source,
    functions=["matmul_shared_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
